import { graphql } from './gql';

/**
 * GraphQL operations used by the cockpit. Types are generated by `npm run codegen`.
 * Every figure is requested with its scope, so the view can print period, records, exclusions and as-of.
 */

export const SCOPE_FIELDS = graphql(`
  fragment ScopeFields on Scope {
    periodLabel
    governingDate
    recordCount
    exclusions
    asOf
    note
  }
`);

export const MEASURE_FIELDS = graphql(`
  fragment MeasureFields on Measure {
    value
    count
    scope {
      ...ScopeFields
    }
  }
`);

export const BUCKET_FIELDS = graphql(`
  fragment BucketFields on Bucket {
    key
    label
    value
    count
    flag
  }
`);

export const OPPORTUNITY_FIELDS = graphql(`
  fragment OpportunityFields on Opportunity {
    guid
    opportunityId
    account
    clientManager
    clientManagerMapped
    owner
    createdOn
    estimatedClose
    actualClose
    statusReason
    statusGroup
    stage
    forecastCategory
    probability
    estimatedGP
    actualGP
    vertical
    salesCycleDays
    flags
    lossReason {
      value
      status
    }
    competitor {
      value
      status
    }
    stageAtLoss {
      value
      status
    }
  }
`);

export const OPTIONS_QUERY = graphql(`
  query Options {
    options {
      asOf
      asOfIso
      source
      sourceKind
      loadedAt
      sampleTargets
      warnings
      currency
      defaultPeriod
      periods {
        id
        label
      }
      clientManagers {
        name
        mapped
      }
      verticals
    }
  }
`);

export const EXECUTIVE_QUERY = graphql(`
  query Executive($filters: FiltersInput!) {
    executive(filters: $filters) {
      periodLabel
      asOf
      target {
        value
        managerCount
        goalCount
        scope {
          ...ScopeFields
        }
      }
      achieved {
        ...MeasureFields
      }
      gap {
        value
        exceeded
        attainment
      }
      openForecast {
        ...MeasureFields
      }
      undated {
        ...MeasureFields
      }
      overdue {
        ...MeasureFields
      }
      warnings {
        kind
        title
        message
      }
      achievedByMonth {
        month
        label
        value
        count
        inPeriod
        afterAsOf
      }
      openByCloseMonth {
        ...BucketFields
      }
      achievedByVertical {
        ...BucketFields
      }
      openByCategory {
        ...BucketFields
      }
      closedOutcomes {
        ...BucketFields
      }
    }
  }
`);

export const CLIENT_MANAGERS_QUERY = graphql(`
  query ClientManagers($filters: FiltersInput!) {
    clientManagers(filters: $filters) {
      scope {
        ...ScopeFields
      }
      opportunityCount
      ownerDiffersCount
      rows {
        name
        mapped
        target
        achieved
        openGP
        gap
        winRate
        won
        lost
        exceptionCount
        opportunityCount
      }
    }
  }
`);

export const PIPELINE_QUERY = graphql(`
  query Pipeline($filters: FiltersInput!) {
    pipeline(filters: $filters) {
      openGP {
        ...MeasureFields
      }
      weightedOpenGP {
        ...MeasureFields
      }
      missingProbability
      undated {
        ...MeasureFields
      }
      overdue {
        ...MeasureFields
      }
      byStage {
        ...BucketFields
      }
      byCloseMonth {
        ...BucketFields
      }
      byCategory {
        ...BucketFields
      }
      opportunities {
        ...OpportunityFields
      }
    }
  }
`);

export const CM360_QUERY = graphql(`
  query Cm360($filters: FiltersInput!) {
    cm360(filters: $filters) {
      clientManager
      mapped
      opportunityCount
      periodLabel
      asOf
      target {
        value
        goalCount
        scope {
          ...ScopeFields
        }
      }
      achieved {
        ...MeasureFields
      }
      gap {
        value
        exceeded
        attainment
      }
      openForecast {
        ...MeasureFields
      }
      weightedOpen {
        ...MeasureFields
      }
      won {
        ...MeasureFields
      }
      lost {
        ...MeasureFields
      }
      winRate
      winRateExcludedCount
      winRateTreatment
      medianSalesCycleDays
      salesCycleSample
      trend {
        month
        label
        won
        lost
        afterAsOf
      }
      deals {
        ...OpportunityFields
      }
    }
  }
`);

export const EXCEPTIONS_QUERY = graphql(`
  query Exceptions($filters: FiltersInput!, $severity: Severity, $ruleId: String) {
    exceptions(filters: $filters, severity: $severity, ruleId: $ruleId) {
      asOf
      total
      filteredTotal
      gpExposure
      bySeverity {
        severity
        count
      }
      byRule {
        count
        rule {
          id
          name
          sourceField
          severity
          appliesTo
        }
      }
      rules {
        id
        name
        severity
      }
      items {
        id
        severity
        gpExposure
        asOf
        rule {
          id
          name
          sourceField
        }
        opportunity {
          ...OpportunityFields
        }
      }
    }
  }
`);

export const DRILL_QUERY = graphql(`
  query Drill($input: DrillInput!) {
    drill(input: $input) {
      title
      governingDate
      amountLabel
      total
      scope {
        ...ScopeFields
      }
      rows {
        amount
        governingDateValue
        opportunity {
          ...OpportunityFields
        }
      }
    }
  }
`);

export const TARGETS_QUERY = graphql(`
  query Targets($filters: FiltersInput!) {
    targets(filters: $filters) {
      total
      scope {
        ...ScopeFields
      }
      rows {
        goalId
        owner
        quarter
        fiscalYear
        metric
        targetAED
        source
      }
    }
  }
`);

export const OPPORTUNITY_QUERY = graphql(`
  query Opportunity($guid: ID!) {
    opportunity(guid: $guid) {
      ...OpportunityFields
    }
  }
`);
